#!/usr/bin/env bash
# test-inline-lane.sh — P2 lean inline execution (spec docs/superpowers/specs/2026-09-27-v9-simplification-design.md
# §8): `execute-bolts` (inline since §8.5; `--agents` retired, §8.6) runs units in ONE context; the CONFLICT gate runs at run start (derive-exec-plan.sh,
# which resumes an open run until --retire) plus a re-bind at each task; the run-boundary gate `conflict_bypassed`
# (validate-bolt-artifacts.sh --conflict-bypass-scan) catches an honest controller's slip — a unit committed past an
# open CONFLICT, a quarantine (its own or a depends_on ancestor's) or a skipped re-bind, judged by the state it landed
# under. Deliberate evasion is out of scope (spec §8.2) and is not tested here.
# Fixture F: U-001 claims lib/config.js (exists); U-002 → U-001; U-003 claims a missing path (a real CONFLICT); U-004
# → U-003 (commented inline list); U-005 → U-004 (commented block list); U-006 independent. F2 create→modify→verify;
# F3 two vaults, colliding ids; F4 a docs/mega-sdd vault, nested unit. Sections: a --pending · b no bind · c run-start
# gate, open run · d the plan · e retire, quarantine paths · k F2 · f the scan · g the hook · m episodes, own_wip,
# rebind_skipped, own_wip at the close, done rule, a literal run · h wiring + docs.   Run: bash tests/v9/test-inline-lane.sh </dev/null
set -u
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"; P="$ROOT/plugins/mega-sdd"; S="$P/scripts"
DEP="$S/derive-exec-plan.sh"; VBA="$S/validate-bolt-artifacts.sh"
rc=0; ok() { echo "PASS: $1"; }; bad() { echo "FAIL: $1"; rc=1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT; export HOME="$T/home"; mkdir -p "$HOME"
G() { git -C "$1" -c user.name=t -c user.email=t@t -c commit.gpgsign=false "${@:2}"; }
J() { python3 -c 'import json,sys; d=json.loads(sys.argv[1]); print(eval(sys.argv[2], {"d": d}))' "$1" "$2" 2>/dev/null; }
JF() { python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); print(eval(sys.argv[2], {"d": d}))' "$1" "$2" 2>/dev/null; }
mkunit() { # <vault> <id> <title> <target> <depends_on line(s)> [extra body] [task_type] [operation]
  mkdir -p "$1/units"
  cat > "$1/units/$2.md" <<EOF
---
id: $2
title: $3
task_type: ${7:-create}
context_source: context.md#f-1
$5
target_files:
  - path: $4
    operation: ${8:-create}
acceptance_test:
  - type: test
    command: test -f $4 && echo $2-ok
    expects: "$2-ok"
---
# $2 — $3

BODY-SENTINEL-$2 the plan points at this file and never inlines it.
${6:-}
EOF
}
brief() { # replica of superpowers task-brief's extractor (fence-aware Task-heading awk)
  awk -v n="$2" '
    /^```/ { infence = !infence }
    !infence && /^#+[ \t]+Task[ \t]+[0-9]+/ { intask = ($0 ~ ("^#+[ \t]+Task[ \t]+" n "([^0-9]|$)")) }
    intask { print }' "$1"
}
bolt() { # <root> <unit> <path> <title> [v5] — a canonical bolt commit (provenance header + trailers)
  mkdir -p "$(dirname "$1/$3")"
  printf '<!-- Generated by mega-sdd execute-bolts 9.0.0\n     Unit: %s · provenance: unit -->\n# %s\n' "$2" "$4" > "$1/$3"
  G "$1" add "$3" && G "$1" commit -qm "feat($2): $4" -m "Unit: $2
SDD-PROVENANCE: mega-sdd/execute-bolts unit=$2${5:+
SDD-Acceptance: v5}"
}
report() { # <vault> <unit> <root> <path> — a minimal bolt-report (orphan gate quiet)
  mkdir -p "$1/bolts/$2"
  printf -- '---\nunit: %s\nstatus: success\ncommits: [%s]\ntarget_hashes:\n  %s: %s\n---\n# Bolt Report — %s\n\nbolt_self_report:\n  confidence: 0.9\n' \
    "$2" "$(git -C "$3" rev-parse --short HEAD)" "$4" "$(shasum -a 256 "$3/$4" | cut -d' ' -f1)" "$2" > "$1/bolts/$2/bolt-report.md"
}
evid() { bash "$S/run-acceptance-tests.sh" --cwd="$1" --unit="$2" --quiet >/dev/null 2>&1; bash "$S/run-postflight-scan.sh" --cwd="$1" --unit="$2" --quiet >/dev/null 2>&1; }
scanat() { bash "$VBA" --cwd="$1" --conflict-bypass-scan --quiet >/dev/null 2>&1; echo $?; }
issues() { JF "$1/.mega-sdd/.bolt-conflict-bypass-state.json" 'sorted({(i["unit_id"], i.get("via")) for i in d["issues"]})'; }
reasons() { JF "$1/.mega-sdd/.bolt-conflict-bypass-state.json" 'sorted({(i["unit_id"], i.get("reason")) for i in d["issues"]})'; }
clone() { rm -rf "$T/$1"; cp -R "$F" "$T/$1"; }
ins() { python3 -c 'import sys; p, a, b = sys.argv[1:4]; t = open(p).read(); open(p, "w").write(t.replace(a + "\n", a + "\n" + b + "\n", 1))' "$@"; }
claim() { printf '\n## Claims\n- C-%s-01 "the legacy adapter exists" — expect: lib/legacy.js — must-exist' "$(printf '%s' "$1" | tr -d -)"; }
census() { # the plan-coverage census is not under test here; stand it in through the census library's own key + digest
  python3 - "$1" "$S/_lib" <<'PYC'
import glob, json, os, sys
root, lib = sys.argv[1], sys.argv[2]; sys.path.insert(0, lib)
doc = {"status": "PASS"}
try:
    import prd_headings as ph
    doc["vaults"] = {ph.vault_key(root, v): {"status": "PASS", "sources": [], "digest": ph.digest(root, v, [])}
                     for v in sorted(glob.glob(os.path.join(root, ".mega-sdd", "vaults", "*")))}
except Exception:
    pass
json.dump(doc, open(os.path.join(root, ".mega-sdd", ".plan-coverage-state.json"), "w"))
PYC
}

# ── fixture F ────────────────────────────────────────────────────────────────
F="$T/proj"; V="$F/.mega-sdd/vaults/demo"; mkdir -p "$V/units" "$F/docs" "$F/lib"
printf '# demo\n' > "$F/README.md"; printf 'module.exports = {};\n' > "$F/lib/config.js"
printf '# Context — demo\n\n## Flows\n- F-1 docs pages\n' > "$V/context.md"; printf '{"vault_layout": 3}\n' > "$V/vault.json"
mkunit "$V" U-001 "Alpha page" docs/alpha.md "depends_on: []" '
## Claims
- C-U001-01 "the config module exists" — expect: lib/config.js — must-exist'
mkunit "$V" U-002 "Beta page" docs/beta.md "depends_on: [U-001]"
mkunit "$V" U-003 "Gamma page" docs/gamma.md "depends_on: []" "$(claim U-003)"
mkunit "$V" U-004 "Delta page" docs/delta.md "depends_on: [U-003]     # waits for the gamma page"
mkunit "$V" U-005 "Epsilon page" docs/epsilon.md "depends_on:
  - U-004   # delta first"
mkunit "$V" U-006 "Zeta page" docs/zeta.md "depends_on: []"
( cd "$F" && git init -q . ) && G "$F" add -A && G "$F" commit -qm "chore: seed"
SEED="$(git -C "$F" rev-parse HEAD)"; census "$F"
dep() { bash "$DEP" --cwd="$F" --vault="$V" --retire >/dev/null 2>&1; bash "$DEP" --cwd="$F" --vault="$V" "$@" 2>"$T/dep.err"; }   # a fresh run
depat() { local r="$1"; shift; bash "$DEP" --cwd="$r" --vault="$r/.mega-sdd/vaults/demo" --retire >/dev/null 2>&1; bash "$DEP" --cwd="$r" --vault="$r/.mega-sdd/vaults/demo" "$@" 2>"$T/dep.err"; }
scan() { scanat "$F"; }; SST="$F/.mega-sdd/.bolt-conflict-bypass-state.json"
plans() { ls "$V/bolts/" 2>/dev/null | grep -cE '^_(exec-plan|inline-ledger)' ; }
qr() { J "$1" '[(q["unit"], q["reason"], q.get("via") or q.get("freshness") or q.get("conflict_ids")) for q in d["quarantined"]]'; }

# ── a: --pending ─────────────────────────────────────────────────────────────
OUT="$(dep --pending)"; R=$?
[ $R -eq 0 ] && [ "$(J "$OUT" 'd["pending"]')" = "['U-001', 'U-002', 'U-003', 'U-004', 'U-005', 'U-006']" ] \
  && ok "a1: --pending lists every not-done unit in topo order (ties by id)" || bad "a1: rc=$R out=$OUT err=$(head -c 200 "$T/dep.err")"
[ "$(plans)" = 0 ] && [ ! -e "$V/bolts" ] && ok "a2: --pending writes nothing" || bad "a2: --pending wrote $(ls "$V/bolts" 2>/dev/null)"
cp "$V/units/U-004.md" "$T/u4.bak"; ins "$V/units/U-004.md" "task_type: create" "status: superseded"
[ "$(J "$(dep --pending)" 'd["pending"]')" = "['U-001', 'U-002', 'U-003', 'U-005', 'U-006']" ] && ok "a3: a status: superseded unit is not pending" || bad "a3: $(dep --pending)"
cp "$T/u4.bak" "$V/units/U-004.md"

# ── b: no bind ran → the dispatch gate's freshness check quarantines every candidate ──
OUT="$(dep)"; R=$?
[ $R -eq 1 ] && [ "$(J "$OUT" 'sorted({(q["reason"], q.get("freshness")) for q in d["quarantined"] if "via" not in q})')" = "[('binding_stale', 'binding_absent')]" ] \
  && [ "$(J "$OUT" 'd["plan"]')" = "None" ] && [ "$(plans)" = 0 ] && ok "b: no binding.json → binding_stale (binding_absent, the run-start freshness check), exit 1, no plan" || bad "b: rc=$R out=$OUT"
[ "$(scan)" = 0 ] && [ "$(JF "$SST" 'd["status"]')" = "PASS" ] && ok "f0: units but no bolt commit → PASS" || bad "f0: $(head -c 300 "$SST" 2>/dev/null)"

# ── c: the up-front bind, then the plan ──────────────────────────────────────
RB="$(bash "$S/rebind-units.sh" --cwd="$F" --vault="$V" --units="$(J "$(dep --pending)" '",".join(d["pending"])')" 2>/dev/null | tail -1)"
[ "$(J "$RB" 'd["conflicts"]')" = "1" ] && ok "c0: rebind-units --units=<pending> binds all six (1 CONFLICT, from the real writer)" || bad "c0: $RB"
OUT="$(dep)"; R=$?; PLAN="$(J "$OUT" 'd["plan"]')"
[ $R -eq 0 ] && [ "$(J "$OUT" 'd["schema"]')" = "exec-plan/1" ] && [ "$(J "$OUT" 'd["in_scope"]')" = "['U-001', 'U-002', 'U-006']" ] \
  && ok "c1: exit 0 with quarantines; in_scope [U-001, U-002, U-006] in topo order" || bad "c1: rc=$R out=$OUT err=$(head -c 300 "$T/dep.err")"
[ "$(qr "$OUT")" = "[('U-003', 'binding_conflict', ['C-U003-01']), ('U-004', 'depends_on_quarantined', 'U-003'), ('U-005', 'depends_on_quarantined', 'U-004')]" ] \
  && ok "c2: U-003 binding_conflict C-U003-01; U-004 via U-003 and U-005 via U-004 (commented depends_on, transitive)" || bad "c2: $(qr "$OUT")"
[ "$PLAN" = "$V/bolts/_exec-plan-$(git -C "$F" rev-parse HEAD | cut -c1-12).md" ] && [ -f "$PLAN" ] && ok "c3: plan at <vault>/bolts/_exec-plan-<head12>.md" || bad "c3: $PLAN"
[ "$(J "$OUT" 'd["halt"]')" = "None" ] && [ "$(J "$OUT" 'd["run_base"]')" = "$SEED" ] && ok "c4: halt null; run_base is the full HEAD" || bad "c4: $OUT"
RU="$(bash "$S/derive-ready-units.sh" --cwd="$F" --vault="$V" 2>/dev/null)"
[ "$(J "$RU" 'sorted((b["unit"], tuple(b["waiting_on"])) for b in d["blocked"])')" = "[('U-002', ('U-001',)), ('U-004', ('U-003',)), ('U-005', ('U-004',))]" ] \
  && ok "c5: derive-ready-units (the default path) reads a commented depends_on too" || bad "c5: $RU"
[ "$(head -1 "$V/bolts/_inline-ledger-$(git -C "$F" rev-parse HEAD | cut -c1-12).md" 2>/dev/null)" = "# inline ledger — plan: $PLAN" ] && ok "c6: the built-in ledger (identity line) is written with the plan (F1/I1)" || bad "c6: $(ls "$V/bolts")"
cp "$PLAN" "$T/plan.c1"; mv "$V/bolts/U-002/binding.json" "$T/b2x.json"; OUT="$(bash "$DEP" --cwd="$F" --vault="$V" 2>/dev/null)"; R=$?; mv "$T/b2x.json" "$V/bolts/U-002/binding.json"
[ $R -eq 0 ] && [ "$(J "$OUT" '(d.get("resumed"), d["plan"], d["in_scope"])')" = "(True, '$PLAN', ['U-001', 'U-002', 'U-006'])" ] && cmp -s "$PLAN" "$T/plan.c1" \
  && ok "c7: an open plan is returned (resumed), never regenerated — (b) re-run mid-task cannot re-plan the run (F1/I1)" || bad "c7: rc=$R $OUT"

# ── d: the plan is superpowers-compatible and carries the run's rules ────────
if [ -f "$PLAN" ]; then
  B1="$(brief "$PLAN" 1)"; B2="$(brief "$PLAN" 2)"
  GC="$(sed -n '/## Global Constraints/,/## Review Focus/p' "$PLAN")"; RF="$(sed -n '/## Review Focus/,/^---$/p' "$PLAN")"
  case "$B1" in "## Task 1: U-001 — Alpha page"*) ok "d1: task 1 brief starts at its heading" ;; *) bad "d1: $(printf '%s' "$B1" | head -2)" ;; esac
  printf '%s' "$B2" | grep -q 'U-002' && ! printf '%s' "$B2" | grep -qE 'U-006|units/U-001' && ! printf '%s' "$B1" | grep -q 'U-002' \
    && ok "d2: each task brief carries its own unit only" || bad "d2: $(printf '%s' "$B2" | grep -n 'U-00' | head -5)"
  HEADS="$(awk '/^```/ { f = !f } !f && /^#+[ \t]+Task[ \t]+[0-9]+/ { print }' "$PLAN")"
  [ "$(printf '%s\n' "$HEADS" | grep -cE '^## Task [123]: U-00[126] — ')" = 3 ] && [ "$(printf '%s\n' "$HEADS" | grep -c .)" = 3 ] && [ -z "$(brief "$PLAN" 4)" ] \
    && ok "d3: exactly three task headings outside a fence" || bad "d3: $HEADS"
  for s in 'finishing-a-development-branch' 'SDD-Acceptance: v5' 'SDD-PROVENANCE: mega-sdd/execute-bolts unit=' 'Generated by mega-sdd execute-bolts' \
           'delivery-check.sh' 'test script' 'Navigation' 'scaffold' 'Empty env' 'wiring' 'U-003' 'U-004' 'U-005' 'main/master' 'no worktree' \
           ':(exclude).mega-sdd' '[DESCRIPTION]' 'no ledger' 'Ruling' 'hard_rule_violated' 'STOPS THE RUN' 'fix(U-XXX)' 'fix(review)' 'never `-A`' \
           'chore(sdd): evidence U-XXX'; do
    grep -qF -- "$s" "$PLAN" && ok "d4: plan carries: $s" || bad "d4: plan lacks: $s"
  done
  grep -qE '^mega-sdd-trace:execute-bolts$' "$PLAN" && ok "d5: the reviewer trace line stands on its own line" || bad "d5: no own-line trace"
  AF="$(sed -n '/^## After the last task/,$p' "$PLAN" | tr '\n' ' ')"; BL="$(brief "$PLAN" 3)"
  printf '%s' "$GC" | grep -F 'Final review and Finishing' | grep -qF '## After the last task' \
    && printf '%s' "$AF" | grep -qE "run-full-suite\.sh.*--base=$SEED.*$SEED\.\.HEAD.*Close: reviewed.*delivery-check\.sh.*run-full-suite\.sh.*--rebind-wip.*evidence run.*conflict-bypass-scan.*--retire" \
    && ok "d6: the close order is inline-run (d): suite, review, fixes, Close: reviewed, delivery-check, suite again, re-bind, evidence, gate, retire" || bad "d6: $AF"
  ! grep -q 'bolt_introduces_locked_drift' "$PLAN" && ok "d16: the plan names no STOP no step can raise (no task runs the per-bolt drift check)" || bad "d16: locked-drift STOP in the plan"
  printf '%s' "$BL" | grep -q '^## After the last task' && printf '%s' "$BL" | grep -qE '^mega-sdd-trace:execute-bolts$' && ! printf '%s' "$B1" | grep -q 'After the last' \
    && ok "d15: the last task's brief carries the close, so a compacted controller keeps the overrides (I4)" || bad "d15: $(printf '%s' "$BL" | tail -3)"
  printf '%s' "$RF" | grep -F 'Out of scope' | grep -q 'U-003' && ok "d7: Review Focus names the quarantined units out of scope" || bad "d7: $RF"
  grep -q 'BODY-SENTINEL' "$PLAN" && bad "d8: the unit body is inlined" || ok "d8: the unit body is pointed at, never inlined"
  grep -qF '$BASE' "$PLAN" && bad "d9: an unset \$BASE in the plan" || ok "d9: no unset \$BASE in the plan"
  for n in 1 2; do
    u="U-00$n"; b="$(brief "$PLAN" $n | sed "s/\.sh' /.sh /g")"
    for s in "$V/units/$u.md" "rebind-units.sh --cwd=$F --vault=$V --units=$u" "run-preflight-scan.sh --cwd=$F --unit=$u" \
             "run-acceptance-tests.sh --cwd=$F --unit=$u" "run-postflight-scan.sh --cwd=$F --unit=$u" "run-code-gates.sh --cwd=$F --base=<BASE>" \
             "--unit=$V/units/$u.md --write" "bolt-report.md" "Unit: $u" "**Task done:**" "**Depends on:**" "_inline-ledger-" "chore(sdd): evidence $u"; do
      printf '%s' "$b" | grep -qF -- "$s" && ok "d10: task $n carries: $s" || bad "d10: task $n lacks: $s"
    done
  done
  printf '%s' "$B2" | grep -qE '^\*\*Depends on:\*\* U-001' && ok "d11: task 2 names its depends_on" || bad "d11: $(printf '%s' "$B2" | grep Depends)"
  printf '%s' "$B1" | grep -qF '2/3/4/5/6/8' && printf '%s' "$B1" | grep -qE 'exit 2: STOP the run' && printf '%s' "$B1" | grep -qF 'hard_rule_violated: STOP the run' \
    && ok "d12: every fatal exit an Expected line names is a STOP" || bad "d12: $(printf '%s' "$B1" | grep -n 'Expected: exit' | head -4)"
  printf '%s' "$B1" | grep -qF '"own_wip": true' && printf '%s' "$B1" | grep -qE 'write-unit-quarantine\.sh.*--unit=U-001 --halt=binding_conflict.*--dependents=' \
    && printf '%s' "$B1" | grep -qF 'go on with the next task' \
    && ok "d13: the re-bind step: own uncommitted target = in progress; a CONFLICT quarantines the unit, skips dependents, continues (K2)" || bad "d13: $(printf '%s' "$B1" | sed -n '/Step 1/,/Step 2/p')"
  printf '%s' "$B1" | grep -qE '^git add -- ' && ! grep -qE '^git add -A' "$PLAN" && ok "d14: commits stage by explicit pathspec, never -A" || bad "d14: $(grep -n 'git add' "$PLAN" | head -3)"
else
  bad "d: no plan to inspect"
fi

# ── e: the quarantine paths ──────────────────────────────────────────────────
WS="$F/.superpowers/sdd/$(basename "$PLAN" .md)"; mkdir -p "$WS"; printf '%s\n' "${PLAN#"$F/"}" > "$WS/plan-path"; clone c2
bash "$DEP" --cwd="$F" --vault="$V" --retire >/dev/null 2>&1; R=$?
[ $R -eq 0 ] && [ "$(plans)" = 0 ] && [ ! -e "$WS" ] && ok "e0: --retire removes the run's plan, ledger and superpowers workspace (the close's last step, C2/F2)" || bad "e0: rc=$R $(ls "$V/bolts") $(ls "$WS" 2>&1)"
bash "$S/write-unit-binding.sh" --cwd="$T/c2" --vault="$T/c2/.mega-sdd/vaults/demo" --unit=U-003 --resolve=C-U003-01=KEEP_CODE --by=user >/dev/null 2>&1
R1="$(J "$(bash "$DEP" --cwd="$T/c2" --vault="$T/c2/.mega-sdd/vaults/demo" 2>/dev/null)" 'd["in_scope"]')"; bash "$DEP" --cwd="$T/c2" --vault="$T/c2/.mega-sdd/vaults/demo" --retire >/dev/null 2>&1
[ "$R1" = "['U-001', 'U-002', 'U-006']" ] && [ "$(J "$(bash "$DEP" --cwd="$T/c2" --vault="$T/c2/.mega-sdd/vaults/demo" 2>/dev/null)" 'd["in_scope"]')" = "['U-001', 'U-002', 'U-003', 'U-004', 'U-005', 'U-006']" ] \
  && ok "e0b: a resolved quarantine waits for the open run; once retired, the next (b) plans it and its dependents (C2)" || bad "e0b: $R1"
mv "$V/bolts/U-002/binding.json" "$T/b2.json"; OUT="$(dep)"; R=$?
[ $R -eq 0 ] && [ "$(qr "$OUT" | grep -c "('U-002', 'binding_stale', 'binding_absent')")" = 1 ] && [ "$(J "$OUT" 'd["in_scope"]')" = "['U-001', 'U-006']" ] \
  && ok "e1: a unit without binding.json is quarantined (binding_absent), the rest proceed" || bad "e1: rc=$R $OUT"
mv "$T/b2.json" "$V/bolts/U-002/binding.json"; OUT="$(dep --units=U-003,U-004)"; R=$?
[ $R -eq 1 ] && [ "$(J "$OUT" 'd["plan"]')" = "None" ] && [ "$(plans)" = 0 ] && [ "$(J "$OUT" '(d["halt"] or {}).get("type")')" = "binding_conflict" ] \
  && J "$OUT" 'd["halt"]["keterangan"]' | grep -q . && ok "e2: every candidate blocked by a CONFLICT → halt binding_conflict with a keterangan, exit 1, stale plans removed" || bad "e2: rc=$R $OUT"
OUT="$(dep --units=U-002)"; R=$?
[ $R -eq 1 ] && [ "$(qr "$OUT")" = "[('U-002', 'depends_on_quarantined', 'U-001')]" ] && [ "$(J "$OUT" 'd["halt"]')" = "None" ] \
  && ok "e3: a dependency neither done nor in scope quarantines the dependent, no halt" || bad "e3: rc=$R $OUT"
printf '# Binding — demo\n\n## Conflicts (1)\n\n### CONFLICT-1 — vault-level contradiction\n- **Verdict**: CONFLICT (BLOCKING)\n' > "$V/binding.md"
OUT="$(dep)"; R=$?
[ $R -eq 1 ] && [ "$(J "$OUT" 'd["halt"]["type"]')" = "binding_conflict" ] && [ "$(J "$OUT" 'd["plan"]')" = "None" ] \
  && ok "e4: a validator drop with no unit_id halts the whole run (binding_conflict)" || bad "e4: rc=$R $OUT"
rm -f "$V/binding.md"; cp "$V/units/U-001.md" "$T/u1.bak"; sed -i.x 's/^depends_on: \[\]$/depends_on: [U-002]/' "$V/units/U-001.md"; rm -f "$V/units/U-001.md.x"
dep >/dev/null; R=$?; dep --pending >/dev/null; R2=$?
[ $R -eq 2 ] && [ $R2 -eq 2 ] && grep -qi 'cycle' "$T/dep.err" && ok "e5: a depends_on cycle → exit 2 with a message (also --pending)" || bad "e5: rc=$R/$R2"
cp "$T/u1.bak" "$V/units/U-001.md"; bash "$DEP" --cwd="$F" >/dev/null 2>&1; [ $? -eq 2 ] && ok "e6: usage (no --vault) → exit 2" || bad "e6: usage exit"
clone cs; printf 'beta\n' > "$T/cs/docs/beta.md"; G "$T/cs" add docs/beta.md && G "$T/cs" commit -qm "chore: hand-written beta"
[ "$(qr "$(depat "$T/cs")" | grep -c "('U-002', 'binding_stale', 'binding_stale')")" = 1 ] && ok "e7: a binding a later non-unit commit made stale → binding_stale (the dispatch gate's function)" || bad "e7: $(depat "$T/cs")"
clone cx; printf '{not json' > "$T/cx/.mega-sdd/vaults/demo/bolts/U-006/binding.json"
[ "$(qr "$(depat "$T/cx")" | grep -c "('U-006', 'binding_conflict'")" = 1 ] && ok "e9: an unparseable binding at run start → binding_conflict (fail closed)" || bad "e9: $(depat "$T/cx")"
dep >/dev/null

# ── k: F2 — create → modify → verify ─────────────────────────────────────────
F2="$T/p2"; V2="$F2/.mega-sdd/vaults/demo"
