printf '# Context\n' > "$V2/context.md"; printf '{"vault_layout": 3}\n' > "$V2/vault.json"; printf '# p2\n' > "$F2/README.md"; ( cd "$F2" && git init -q . ) && G "$F2" add -A && G "$F2" commit -qm "chore: seed"
