[ -n "$PLAN2" ] && [ "$(J "$RS" '(d.get("resumed"), d["plan"])')" = "(True, '$PLAN2')" ] && [ "$NPLAN" != "$PLAN2" ] && [ -f "$NPLAN" ] && [ ! -e "$PLAN2" ] \
