[ $R -eq 0 ] && [ "$(J "$OUT" 'd["in_scope"]')" = "['U-002']" ] && [ "$(J "$OUT" 'd["done"]')" = "['U-001']" ] && ok "f5: a done dependency lets the dependent run" || bad "f5: rc=$R $OUT"
