# ── g: the hook reads the state; the state file is guarded ───────────────────
hook() { printf '%s' "$1" | ( cd "$F" && bash "$P/hooks/pre-tool-use" 2>/dev/null ); }
deny() { case "$1" in *'"permissionDecision": "deny"'*) return 0 ;; esac; return 1; }
pj() { python3 -c 'import json,sys; print(json.dumps({"session_id":"sess-inline-0001","cwd":sys.argv[1],"tool_name":sys.argv[2],"tool_input":json.loads(sys.argv[3])}))' "$F" "$1" "$2"; }
pjf() { python3 -c 'import json,sys; print(json.dumps({"session_id":"sess-inline-0001","cwd":sys.argv[1],"tool_name":sys.argv[2],"tool_input":{"file_path":sys.argv[3],"content":"{}","old_string":"a","new_string":"b"}}))' "$F" "$1" "$2"; }
census "$F"
SKILL_P="$(pj Skill '{"skill":"mega-sdd:execute-bolts","args":"--all --lite --inline"}')"
O="$(hook "$SKILL_P")"
case "$O" in *'"permissionDecision": "deny"'*conflict-bypass*'U-003 open_conflict'*'U-004 depends_on_blocked via U-003'*) ok "g1: Skill execute-bolts DENIED on a FAIL bypass state, naming each unit's reason" ;;
  *) bad "g1: $(printf '%s' "$O" | head -c 600)" ;; esac
for tool in Write Edit; do
  deny "$(hook "$(pjf $tool "$SST")")" && ok "g3: $tool of the bypass state is denied" || bad "g3: $tool allowed"
done
for c in "rm .mega-sdd/.bolt-conflict-bypass-state.json" "echo '{}' > .mega-sdd/.bolt-conflict-bypass-state.json"; do
  deny "$(hook "$(pj Bash "$(python3 -c 'import json,sys; print(json.dumps({"command": sys.argv[1]}))' "$c")")")" && ok "g4: Bash '$c' is denied" || bad "g4: Bash '$c' allowed"
done
O="$(hook "$(pjf Write "$F/.mega-sdd/.bolt-acceptance-state.json")")"
case "$O" in *'"permissionDecision": "deny"'*bolt-conflict-bypass*) ok "g5: the Write/Edit block message enumerates bolt-conflict-bypass" ;; *) bad "g5: $(printf '%s' "$O" | head -c 300)" ;; esac
rm -f "$F/.mega-sdd/.stop-scan-stamp" "$SST"
printf '{"session_id":"sess-inline-0001","cwd":"%s","hook_event_name":"Stop"}' "$F" | ( cd "$F" && bash "$P/hooks/stop" >/dev/null 2>&1 )
[ "$(JF "$SST" 'd["status"]')" = "FAIL" ] && ok "g6: the Stop hook writes the FAIL bypass state" || bad "g6: $(head -c 300 "$SST" 2>/dev/null)"

# ── f (cont.): a re-bind never clears it; the human decision does ────────────
sleep 1; bash "$S/rebind-units.sh" --cwd="$F" --vault="$V" --units=U-003 >/dev/null 2>&1
[ "$(scan)" = 1 ] && [ "$(issues "$F")" = "[('U-003', None), ('U-004', 'U-003'), ('U-005', 'U-003')]" ] \
  && ok "f14: a re-bind that keeps the CONFLICT open never clears the bypass, own or via" || bad "f14: $(issues "$F")"
sleep 1; printf 'fix\n' >> "$F/docs/gamma.md"; G "$F" commit -qam "fix(U-003): gamma wording" -m "Unit: U-003"
[ "$(scan)" = 1 ] && ok "f15: a later U-003 commit past the open CONFLICT → FAIL" || bad "f15: $(issues "$F")"
for u in U-003 U-001; do
  for cid in $(JF "$V/bolts/$u/binding.json" '" ".join(c["id"] for c in d["claims"] if c["verdict"] == "CONFLICT" and not c.get("resolution"))'); do
    bash "$S/write-unit-binding.sh" --cwd="$F" --vault="$V" --unit=$u --resolve="$cid=KEEP_CODE" --by=user >/dev/null 2>&1
  done
done
[ "$(scan)" = 0 ] && ok "f16: PASS after the human's write-unit-binding --resolve (own and via released)" || bad "f16: $(issues "$F")"
report "$V" U-003 "$F" docs/gamma.md
deny "$(hook "$SKILL_P")" && bad "g7: Skill still denied with the bypass state PASS" || ok "g7: Skill execute-bolts ALLOWED once the bypass state is PASS"
cp "$V/bolts/U-003/binding.json" "$T/b3.json"
clone cl; printf '{"schema": "unit-binding/1", "unit": "U-003", "claims": [{"id": "C-U003-01", "kind": "fs_must_exist", "expect": "lib/legacy.js", "verdict": "CONFLICT"}]}\n' > "$T/cl/.mega-sdd/vaults/demo/bolts/U-003/binding.json"
[ "$(scanat "$T/cl")" = 0 ] && [ "$(JF "$T/cl/.mega-sdd/.bolt-conflict-bypass-state.json" 'd["legacy_advisory"]')" = "['U-003']" ] \
  && ok "f17: a legacy binding with no CONFLICT time → advisory only, PASS" || bad "f17: $(head -c 400 "$T/cl/.mega-sdd/.bolt-conflict-bypass-state.json")"
printf '{not json' > "$V/bolts/U-003/binding.json"
[ "$(scan)" = 1 ] && [ "$(reasons "$F")" = "[('U-003', 'binding_unparseable')]" ] && ok "f18: an unparseable binding of a bolted unit → FAIL (fail closed)" || bad "f18: $(reasons "$F")"
cp "$T/b3.json" "$V/bolts/U-003/binding.json"
F5="$T/p5"; mkdir -p "$F5/.mega-sdd"; ( cd "$F5" && git init -q . ) && printf 'x\n' > "$F5/a" && G "$F5" add a && G "$F5" commit -qm init
[ "$(scanat "$F5")" = 0 ] && [ "$(JF "$F5/.mega-sdd/.bolt-conflict-bypass-state.json" 'd.get("fast_path")')" = "no_bolt_artifacts" ] && ok "f19: no bolts/U-XXX entry → PASS on the 0-fork fast path" || bad "f19"
F4="$T/p4"; V4="$F4/docs/mega-sdd/vaults/demo"; mkdir -p "$V4/units/U-002"; printf '# c\n' > "$V4/context.md"
mkunit "$V4" U-001 "Gamma" docs/g.md "depends_on: []" "$(claim U-001)"; mkunit "$V4" U-002 "Delta" docs/d.md "depends_on: [U-001]"; mv "$V4/units/U-002.md" "$V4/units/U-002/unit.md"
