bash "$S/rebind-units.sh" --cwd="$F4" --vault="$V4" --units=U-001,U-002 >/dev/null 2>&1
OUT="$(bash "$DEP" --cwd="$F4" --vault="$V4" 2>/dev/null)"
[ "$(qr "$OUT")" = "[('U-001', 'binding_conflict', ['C-U001-01']), ('U-002', 'depends_on_quarantined', 'U-001')]" ] && ok "f20: a docs/mega-sdd vault's CONFLICT unit is quarantined at run start" || bad "f20: $OUT"
sleep 1; bolt "$F4" U-002 docs/d.md "Delta"
[ "$(scanat "$F4")" = 1 ] && [ "$(issues "$F4")" = "[('U-002', 'U-001')]" ] && ok "f21: a nested-layout dependent in a docs/mega-sdd vault → FAIL via U-001" || bad "f21: $(issues "$F4")"
F3="$T/p3"; mkdir -p "$F3/.mega-sdd/vaults"
for vn in alpha beta; do mkdir -p "$F3/.mega-sdd/vaults/$vn"; printf '# c\n' > "$F3/.mega-sdd/vaults/$vn/context.md"; done
