printf '# p3\n' > "$F3/README.md"; ( cd "$F3" && git init -q . ) && G "$F3" add -A && G "$F3" commit -qm seed
for vn in alpha beta; do bash "$S/rebind-units.sh" --cwd="$F3" --vault="$F3/.mega-sdd/vaults/$vn" --units=U-001 >/dev/null 2>&1; done
sleep 1; bolt "$F3" U-001 docs/b1.md "Beta one"
[ "$(scanat "$F3")" = 1 ] && [ "$(JF "$F3/.mega-sdd/.bolt-conflict-bypass-state.json" '[i["vault"] for i in d["issues"]]')" = "['.mega-sdd/vaults/beta']" ] \
  && ok "f22: a colliding unit id is checked in the vault its commit touched" || bad "f22: $(head -c 400 "$F3/.mega-sdd/.bolt-conflict-bypass-state.json")"

# ── m: a commit is judged against the CONFLICT state it landed under ─────────
MK() { rm -rf "$1"; mkdir -p "$1/.mega-sdd/vaults/demo/units" "$1/lib" "$1/docs"; printf '# m\n' > "$1/README.md"; printf 'module.exports = {};\n' > "$1/lib/config.js"
  printf '# Context — demo\n' > "$1/.mega-sdd/vaults/demo/context.md"; printf '{"vault_layout": 3}\n' > "$1/.mega-sdd/vaults/demo/vault.json"; }
MV() { printf '%s/.mega-sdd/vaults/demo' "$1"; }
seed() { ( cd "$1" && git init -q . ) && G "$1" add -A && G "$1" commit -qm "chore: seed"; }
rb() { bash "$S/rebind-units.sh" --cwd="$1" --vault="$(MV "$1")" --units="$2" >/dev/null 2>&1; }
cl() { JF "$(MV "$1")/bolts/$2/binding.json" '[(c["id"], c["verdict"]) for c in d["claims"] if not c.get("resolution")]'; }
resolve() { bash "$S/write-unit-binding.sh" --cwd="$1" --vault="$(MV "$1")" --unit="$2" --resolve="$3=KEEP_CODE" --by=user >/dev/null 2>&1; }
cpx() { rm -rf "$2"; cp -R "$1" "$2"; }
# m1: the bypass commit makes its own CONFLICT claim true; the re-bind that closes it never launders it
M1="$T/m1"; MK "$M1"; mkunit "$(MV "$M1")" U-001 "Legacy adapter" src/legacy.js "depends_on: []" "" modify modify; seed "$M1"; rb "$M1" U-001
[ "$(cl "$M1" U-001)" = "[('C-U001-A01', 'CONFLICT')]" ] && ok "m1a: a modify target that does not exist → CONFLICT C-U001-A01" || bad "m1a: $(cl "$M1" U-001)"
cpx "$M1" "$T/m1s"; sleep 1; bolt "$M1" U-001 src/legacy.js "Legacy adapter"; r1="$(scanat "$M1")"; rb "$M1" U-001
[ "$r1" = 1 ] && [ "$(cl "$M1" U-001)" = "[('C-U001-A01', 'CONFIRMED')]" ] && [ "$(scanat "$M1")" = 1 ] && [ "$(reasons "$M1")" = "[('U-001', 'closed_conflict')]" ] \
  && [ "$(JF "$(MV "$M1")/bolts/U-001/binding.json" '[e["id"] for e in d["conflict_history"]]')" = "['C-U001-A01']" ] \
  && ok "m1b: the re-bind closes the CONFLICT into conflict_history; the commit made while it was open stays a bypass" || bad "m1b: $r1 $(cl "$M1" U-001) $(reasons "$M1")"
resolve "$M1" U-001 C-U001-A01 && [ "$(scanat "$M1")" = 0 ] && ok "m1c: the human decision on the closed episode (write-unit-binding --resolve) releases it" || bad "m1c: $(reasons "$M1")"
ON="$(JF "$(MV "$T/m1s")/bolts/U-001/binding.json" '[c["conflict_since"] for c in d["claims"] if c["id"] == "C-U001-A01"][0]')"
mkdir -p "$T/m1s/src"; printf 'x\n' > "$T/m1s/src/legacy.js"; G "$T/m1s" add src
GIT_AUTHOR_DATE="$ON" GIT_COMMITTER_DATE="$ON" G "$T/m1s" commit -qm "chore: legacy adapter" -m "unit: U-001"
[ "$(scanat "$T/m1s")" = 1 ] && ok "m1d: a commit in the same second the CONFLICT opened counts (>=), a lowercase unit: trailer too (git's parse)" || bad "m1d: $(reasons "$T/m1s")"
M1F="$T/m1f"; MK "$M1F"; mkunit "$(MV "$M1F")" U-001 "Legacy adapter" src/legacy.js "depends_on: []" "" modify modify
mkunit "$(MV "$M1F")" U-002 "Beta page" docs/beta.md "depends_on: [U-001]"; seed "$M1F"; rb "$M1F" U-001,U-002
sleep 1; bolt "$M1F" U-002 docs/beta.md "Beta page"; r1="$(scanat "$M1F")"
sleep 1; mkdir -p "$M1F/src"; printf 'x\n' > "$M1F/src/legacy.js"; G "$M1F" add src && G "$M1F" commit -qm "chore: add the legacy adapter"; rb "$M1F" U-001
[ "$r1" = 1 ] && [ "$(cl "$M1F" U-001)" = "[('C-U001-A01', 'CONFIRMED')]" ] && [ "$(issues "$M1F" | grep -c "('U-002', 'U-001')")" = 1 ] && [ "$(scanat "$M1F")" = 1 ] \
  && ok "m1e: a later re-bind that closes the ancestor's CONFLICT does not release a dependent committed inside it" || bad "m1e: $r1 $(issues "$M1F")"
# m2: a migrated vault (first bind after the commit) passes; an ancestor done only by its own bypass does not release its dependent
M2="$T/m2"; MK "$M2"; mkunit "$(MV "$M2")" U-006 "Zeta page" docs/zeta.md "depends_on: []"; seed "$M2"; sleep 1; bolt "$M2" U-006 docs/zeta.md "Zeta page"; sleep 1; rb "$M2" U-006
[ "$(scanat "$M2")" = 0 ] && ok "m2a: a unit implemented before its first bind (a migrated vault) → PASS" || bad "m2a: $(reasons "$M2")"
